const PAGE_SIZE=8;
export const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
export function safeLink(raw){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
export function canonicalKey(row){const raw=row?.canonicalUrl||row?.url;if(!raw)return null;try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol))return null;u.hash='';for(const k of [...u.searchParams.keys()])if(/^(utm_.+|fbclid|gclid)$/i.test(k))u.searchParams.delete(k);return u.href.replace(/\/$/,'')}catch{return null}}
export function distanceKm(a,b){const rad=x=>x*Math.PI/180, dLat=rad(b.lat-a.lat),dLon=rad(b.lon-a.lon),x=Math.sin(dLat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
export function escapeText(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
export function dedupe(rows){const seen=new Set;return rows.filter(r=>{const k=canonicalKey(r);if(!k)return true;if(seen.has(k))return false;seen.add(k);return true})}
export function paginate(rows,page,size=PAGE_SIZE){const pages=Math.max(1,Math.ceil(rows.length/size));const p=Math.min(Math.max(1,page),pages);return {page:p,pages,items:rows.slice((p-1)*size,p*size)}}
if(typeof document!=='undefined'){
const $=id=>document.getElementById(id);let records=[],active='web',page=1,delayNext=false,errorNext=false;
const tabs=['web','images','news','shopping','research','discussions','venues','edge-cases'];
function text(el,value){el.textContent=value??''}
function makeCard(r){const article=document.createElement('article');article.className='card';const title=document.createElement('h2');title.textContent=r.title||r.name||'(missing title)';article.append(title);const status=document.createElement('span');status.className=`badge ${r.state||'unknown'}`;status.textContent=r.state||'unknown';article.append(status);if(r.snippet){const p=document.createElement('p');p.textContent=r.snippet;article.append(p)}if(r.type==='venues'){const p=document.createElement('p');p.textContent=`${r.category||'Uncategorized'} · ${r.address||'Address unavailable'} · ${r.hoursText||'Hours unknown'}`;article.append(p);const detail=document.createElement('p');detail.className='small';detail.textContent=`Rating: ${r.rating??'—'} · Price: ${r.price||'—'} · ${r.phone||'No phone'}`;article.append(detail);if(r.coordinates){const d=document.createElement('p');d.className='small';d.textContent=`${r.coordinates.lat.toFixed(4)}, ${r.coordinates.lon.toFixed(4)} · ${distanceKm({lat:37.77,lon:-122.42},r.coordinates).toFixed(1)} km from test point`;article.append(d)}if(r.osm){const a=document.createElement('p');a.className='attribution';a.textContent=`OSM ${r.osm.type}/${r.osm.id} · ${r.osm.attribution}`;article.append(a)}}const link=safeLink(r.url);if(link){const a=document.createElement('a');a.href=link;a.rel='noopener noreferrer';a.target='_blank';a.textContent='Open safe fixture link';article.append(a)}else if(r.url){const p=document.createElement('p');p.className='small';p.textContent='Unsafe or malformed link suppressed';article.append(p)}for(const t of r.tags||[]){const span=document.createElement('span');span.className='tag';span.textContent=t;article.append(span)}return article}
function filtered(){const q=normalize($('query').value.trim()),cat=$('category').value,state=$('state').value,radius=Number($('radius').value||0);let list=records.filter(r=>r.type===active&&( !q||normalize([r.title,r.name,r.snippet,r.address,r.category,...(r.tags||[])].join(' ')).includes(q))&&(!cat||r.category===cat)&&(!state||(r.state===state||r.hoursStatus===state)));list=dedupe(list);if(active==='venues'&&radius>0)list=list.filter(r=>r.coordinates&&distanceKm({lat:37.77,lon:-122.42},r.coordinates)<=radius);const sort=$('sort').value;list.sort((a,b)=>sort==='rating'?(b.rating||0)-(a.rating||0):sort==='distance'&&a.coordinates&&b.coordinates?distanceKm({lat:37.77,lon:-122.42},a.coordinates)-distanceKm({lat:37.77,lon:-122.42},b.coordinates):(a.title||'').localeCompare(b.title||''));return list}
function render(){const list=filtered(),pg=paginate(list,page);page=pg.page;const root=$('results');root.replaceChildren();if(!list.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=$('query').value.includes('no-such-fixture-000')?'No results for this deliberate zero-result query.':'No matching fixtures. Adjust search or filters.';root.append(empty)}else for(const row of pg.items)root.append(makeCard(row));text($('summary'),`${list.length} results · ${active==='venues'?'synthetic venues':'local fixtures'} · page ${pg.page} of ${pg.pages}`);text($('pageinfo'),`${Math.min((pg.page-1)*PAGE_SIZE+1,list.length)}–${Math.min(pg.page*PAGE_SIZE,list.length)} of ${list.length}`);const pager=$('pager');pager.replaceChildren();for(const [label,disabled,next] of [['Previous',pg.page<=1,pg.page-1],['Next',pg.page>=pg.pages,pg.page+1]]){const b=document.createElement('button');b.className='action';b.type='button';b.textContent=label;b.disabled=disabled;b.setAttribute('aria-label',`${label} page`);b.onclick=()=>{page=next;render()};pager.append(b)}}
function activate(tab){active=tab;page=1;for(const b of $('tabs').children){const yes=b.dataset.type===tab;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1}const cats=[...new Set(records.filter(r=>r.type===active&&r.category).map(r=>r.category))].sort();$('category').replaceChildren(new Option('All categories',''),...cats.map(c=>new Option(c,c)));$('category').disabled=!cats.length;render()}
for(const type of tabs){const b=document.createElement('button');b.type='button';b.setAttribute('role','tab');b.dataset.type=type;b.textContent=type==='edge-cases'?'Edge Cases':type[0].toUpperCase()+type.slice(1);b.onclick=()=>activate(type);$('tabs').append(b)}
for(const id of ['query','category','state','sort','radius'])$(id).addEventListener(id==='query'?'input':'change',()=>{page=1;render()});$('reset').onclick=()=>{$('query').value='';$('state').value='';$('sort').value='title';$('radius').value='15';activate('web')};$('slow').onclick=async()=>{delayNext=true;text($('summary'),'Slow simulation armed (700 ms)…');await new Promise(r=>setTimeout(r,700));delayNext=false;render()};$('fail').onclick=()=>{errorNext=true;text($('summary'),'Simulated local error: fixture source unavailable.');$('results').replaceChildren();const e=document.createElement('div');e.className='empty';e.setAttribute('role','alert');e.textContent='Simulated error — no network request was made. Use Reset to recover.';$('results').append(e)};
fetch('./data.json').then(r=>{if(!r.ok)throw Error('Fixture JSON unavailable');return r.json()}).then(data=>{records=data.records;activate('web')}).catch(e=>{text($('summary'),e.message);$('results').replaceChildren()});
}
